local CandleMoldMaker = {}
local PRODUCTS = {
    iron_candle_mold = { name = "Železni model za sveče", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 165, prestige = 3, happiness = 2, description = "Železni model za litje sveč." },
    bronze_candle_mold = { name = "Bronast model za sveče", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 400, prestige = 5, happiness = 3, description = "Bronast model za fine sveče." },
    silver_candle_mold = { name = "Srebrni model za sveče", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 970, prestige = 10, happiness = 4, description = "Srebrni model za plemiške sveče." },
    gilded_candle_mold = { name = "Pozlačeni model za sveče", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 2100, prestige = 19, happiness = 5, description = "Pozlačeni model za dvorne sveče." },
    jewel_set_candle_mold = { name = "Draguljasti model za sveče", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4500, prestige = 35, happiness = 7, description = "Draguljasti model za kraljevske sveče." },
    royal_sovereign_candle_mold = { name = "Kraljevski suvereni model za sveče", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 9700, prestige = 67, happiness = 13, description = "Suvereni model z biseri za krono." },
}
local BUILDINGS = {
    candlemold_workshop = { name = "Modelna delavnica", cost = { gold = 330, wood = 180, stone = 130, iron = 8 }, upkeep = 6, qualityBonus = 5 },
    candlemold_house = { name = "Modelna hiša", cost = { gold = 1200, wood = 360, stone = 270, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_candlemold_atelier = { name = "Mojstrski modelni atelje", cost = { gold = 3010, wood = 420, stone = 520, silver = 35, gold = 7 }, upkeep = 71, qualityBonus = 30 },
    sovereign_candlemold_palace = { name = "Suverena modelna palača", cost = { gold = 13050, wood = 645, stone = 830, gold = 84, jewel = 19 }, upkeep = 255, qualityBonus = 55, prestigeBonus = 50 },
}
CandleMoldMaker.ironStock = 14; CandleMoldMaker.bronzeStock = 12; CandleMoldMaker.woodStock = 14; CandleMoldMaker.leatherStock = 8; CandleMoldMaker.silverStock = 8; CandleMoldMaker.goldStock = 6; CandleMoldMaker.jewelStock = 4; CandleMoldMaker.pearlStock = 4
CandleMoldMaker.productStock = {}; CandleMoldMaker.buildings = {}; CandleMoldMaker.maker = nil; CandleMoldMaker.activeMaking = {}; CandleMoldMaker.totalProducts = 0; CandleMoldMaker.dayTimer = 0
function CandleMoldMaker.init() CandleMoldMaker.ironStock=14; CandleMoldMaker.bronzeStock=12; CandleMoldMaker.woodStock=14; CandleMoldMaker.leatherStock=8; CandleMoldMaker.silverStock=8; CandleMoldMaker.goldStock=6; CandleMoldMaker.jewelStock=4; CandleMoldMaker.pearlStock=4; CandleMoldMaker.productStock={}; CandleMoldMaker.buildings={}; CandleMoldMaker.maker=nil; CandleMoldMaker.activeMaking={}; CandleMoldMaker.totalProducts=0; CandleMoldMaker.dayTimer=0; print("[CandleMoldMaker] Royal Candle Mold Maker System initialized (6 products, 4 buildings)") end
function CandleMoldMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CandleMoldMaker.maker={name=n or ("Modelar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Modelar najet: %s (spretnost: %d)",CandleMoldMaker.maker.name,s),"success") end; return true end
function CandleMoldMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CandleMoldMaker.build(id) local ok,e=CandleMoldMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CandleMoldMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CandleMoldMaker.getQualityBonus() local b=0; for _,bd in ipairs(CandleMoldMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CandleMoldMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CandleMoldMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CandleMoldMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CandleMoldMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CandleMoldMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CandleMoldMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CandleMoldMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CandleMoldMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CandleMoldMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CandleMoldMaker.buildings==0 then return false,"Potrebna modelna delavnica" end; if not CandleMoldMaker.maker then return false,"Potreben modelar" end; return true end
function CandleMoldMaker.make(pt,qty) qty=qty or 1; local ok,e=CandleMoldMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CandleMoldMaker.ironStock=CandleMoldMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CandleMoldMaker.bronzeStock=CandleMoldMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CandleMoldMaker.woodStock=CandleMoldMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CandleMoldMaker.leatherStock=CandleMoldMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CandleMoldMaker.silverStock=CandleMoldMaker.silverStock-d.silverCost*qty end; if d.goldCost then CandleMoldMaker.goldStock=CandleMoldMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CandleMoldMaker.jewelStock=CandleMoldMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CandleMoldMaker.pearlStock=CandleMoldMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CandleMoldMaker.maker then t=math.max(1,t-math.floor(CandleMoldMaker.maker.skill/13)) end; table.insert(CandleMoldMaker.activeMaking,{id="candlemold_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CandleMoldMaker.completeMaking(m) local q=1.0+(CandleMoldMaker.getQualityBonus()/100); if CandleMoldMaker.maker then q=q+(CandleMoldMaker.maker.skill/140) end; q=math.min(2.5,q); CandleMoldMaker.productStock[m.productType]=(CandleMoldMaker.productStock[m.productType] or 0)+m.quantity; CandleMoldMaker.totalProducts=CandleMoldMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CandleMoldMaker.maker then CandleMoldMaker.maker.itemsMade=CandleMoldMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CandleMoldMaker.maker.skill=math.min(100,CandleMoldMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Model izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"candlemold.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CandleMoldMaker.update(dt) if not _G.state then return end; CandleMoldMaker.dayTimer=CandleMoldMaker.dayTimer+dt; if CandleMoldMaker.dayTimer>=30 then CandleMoldMaker.dayTimer=0; for i=#CandleMoldMaker.activeMaking,1,-1 do local m=CandleMoldMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CandleMoldMaker.completeMaking(m); table.remove(CandleMoldMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CandleMoldMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CandleMoldMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CandleMoldMaker.getStats() return {ironStock=CandleMoldMaker.ironStock,bronzeStock=CandleMoldMaker.bronzeStock,woodStock=CandleMoldMaker.woodStock,leatherStock=CandleMoldMaker.leatherStock,silverStock=CandleMoldMaker.silverStock,goldStock=CandleMoldMaker.goldStock,jewelStock=CandleMoldMaker.jewelStock,pearlStock=CandleMoldMaker.pearlStock,productStock=CandleMoldMaker.productStock,numBuildings=#CandleMoldMaker.buildings,hasMaker=CandleMoldMaker.maker~=nil,makerName=CandleMoldMaker.maker and CandleMoldMaker.maker.name or "—",makerSkill=CandleMoldMaker.maker and CandleMoldMaker.maker.skill or 0,activeMaking=#CandleMoldMaker.activeMaking,totalProducts=CandleMoldMaker.totalProducts} end
return CandleMoldMaker
